/**
 * Whaleal 统一法务页模板（10 语）。
 *
 * 由 gatsby-node.js 的 createPages 生成：
 *   /legal/terms/  /legal/privacy/  /legal/aup/  （各 10 语）
 *
 * 🔴 2026-11-28 裁决：条款性内容只保留英文原文，不做 10 语翻译。
 *    Cart（Shopify 应用）的合规披露独立为英文单语页 /legal/cart/，本模板
 *    只渲染平台条款（从 console 迁来的 10 语 legalDocs.js），不合并任何附录。
 * 🔴 法务措辞不擅自机翻：zh/en 取 console 精翻、8 语取已验证译文表。
 *
 * @since 2026-11-28
 */
import React from 'react';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { LEGAL_DOCS } from '../data/legalDocs';
import '../styles/legal-page.css';
import { usePageI18n } from '../i18n';
import { localePath } from '../i18n/config';

const CJK = new Set(['zh', 'zh-Hant']);

function Block({ block }) {
  const v = block.v;
  if (block.t === 'h2') return <h2>{v}</h2>;
  if (block.t === 'h3') return <h3>{v}</h3>;
  if (block.t === 'li') return <li>{v}</li>;
  return <p>{v}</p>;
}

export default function LegalDocPage({ pageContext }) {
  const { locale } = usePageI18n(pageContext);
  const lang = locale || 'en';
  const kind = pageContext.kind;
  const doc = (LEGAL_DOCS[lang] || LEGAL_DOCS.en)[kind];
  // 🔴 2026-11-28 裁决：条款性内容只保留英文。Cart 的 Shopify 合规披露独立为
  //    英文单语页 /legal/cart/，不再作为 10 语附录合并进平台条款。
  const blocks = doc.blocks;
  const path = `/legal/${kind}/`;
  const brand = CJK.has(lang) ? '鲸联' : 'Whaleal';
  const title = `${doc.title} — ${brand}`;

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={title}
        description={doc.blocks.find((b) => b.t === 'p')?.v || doc.title}
        pathname={path}
        canonicalPath={localePath(path, lang)}
        softwareApp={false}
        breadcrumbs={[
          { name: lang === 'zh' ? '首页' : 'Home', path: localePath('/', lang) },
          { name: doc.title, path: localePath(path, lang) },
        ]}
        hrefLang={lang}
      />
      <div className="page-container about-page">
        <div className="page-header about-header">
          <h1>{doc.title}</h1>
          <p>{doc.meta.updated} · {doc.meta.effective}</p>
        </div>
        <div className="about-content">
          {blocks.map((b, i) => <Block key={i} block={b} />)}
        </div>
      </div>
    </Layout>
  );
}
